window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-58885ed9769de68b"]={"versions": [{"id": "FIG-58885ed9769de68b", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Objektdiagramm (M1-Instanziierungsebene des AUTOSAR ECU Configuration Metamodells).\n</li><li><strong>Technischer Zweck:</strong> Spezifikationsbeispiel zur Veranschaulichung der Modellierung von Referenzbeziehungen (<code>ReferenceDef</code>) zwischen Konfigurationscontainern (<code>ParamConfContainerDef</code>) innerhalb der BSW-Parametrisierung (ECUC Parameter Definition). \n</li><li><strong>Funktionale Einordnung:</strong> Dient als formale Schablone für Konfigurationsgeneratoren und XML-/ARXML-Schemata, demonstriert anhand der Zuordnung von OS-Schedule-Tables zu OS-Applications im AUTOSAR OS.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>OsApplication : ParamConfContainerDef</code></strong>\n<ul class=\"fig-list\"><li>Metamodell-Instanz zur Container-Definition einer OS-Applikation.\n</li><li>Attributierung: <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code> (in einer ECU-Konfiguration können null bis beliebig viele Instanzen dieses Containers existieren).\n</li></ul>\n</li><li><strong><code>OsAppScheduleTableRef : ReferenceDef</code></strong>\n<ul class=\"fig-list\"><li>Metamodell-Instanz zur Definition eines Referenzparameters.\n</li><li>Attributierung: <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code> (eine OS-Application kann null bis beliebig viele Schedule Tables referenzieren).\n</li></ul>\n</li><li><strong><code>OsScheduleTable : ParamConfContainerDef</code></strong>\n<ul class=\"fig-list\"><li>Metamodell-Instanz zur Definition des Ziel-Containers für Scheduling-Tabellen.\n</li><li>Attributierung: <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>.\n</li></ul>\n</li><li><strong>Beziehungen:</strong>\n<ul class=\"fig-list\"><li><strong>Komposition (<code>+reference</code>):</strong> Strenge Teil-Ganzes-Beziehung (ausgefüllte Raute bei <code>OsApplication</code>). Der Referenzparameter <code>OsAppScheduleTableRef</code> ist strukturell und existenziell im definierenden Container <code>OsApplication</code> gekapselt.\n</li><li><strong>Gerichtete Assoziation (<code>+destination</code>):</strong> Unidirektionale Zielreferenz (offene Pfeilspitze) von <code>OsAppScheduleTableRef</code> auf den Ziel-Container <code>OsScheduleTable</code>.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<ul class=\"fig-list\"><li><strong>Nicht zutreffend:</strong> Statisches Daten-/Metamodell-Diagramm ohne Laufzeitsequenz.\n</li><li><strong>Prozessuale Zuordnung (Design-/Generierungszeit):</strong> Die Auswertung der Referenz erfolgt rein statisch während des Konfigurations- und Generierungsschritts (Tooling). Das ECUC-Validierungswerkzeug prüft die Gültigkeit des Pfadverweises (<code>VALUE-REF</code>) und generiert daraus statische C-Deskriptoren, Bitmasken oder Konstantenarrays für das AUTOSAR OS.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Serialisierung:</strong> \n<ul class=\"fig-list\"><li>Im Konfigurationsmodell (<code>EcucParameterValues</code>) entspricht dies einem <code>EcucReferenceValue</code>, der innerhalb des übergeordneten <code>EcucContainerValue</code> (<code>OsApplication</code>) liegt und über dessen Zielpfad auf einen separaten <code>EcucContainerValue</code> (<code>OsScheduleTable</code>) zeigt.\n</li></ul>\n</li><li><strong>OS-Sicherheits- &amp; Rechtemodell:</strong>\n<ul class=\"fig-list\"><li>Konfiguriert im AUTOSAR OS die Zugriffsberechtigungen (<code>ACCESSING-APPLICATION</code>) bzw. Ownership-Relationen. Tasks oder ISRs, die der jeweiligen <code>OsApplication</code> zugeordnet sind, leiten hierüber ihr Recht ab, Steuerungs-APIs auf der Ziel-Schedule-Table aufzurufen (z. B. <code>StartScheduleTableRel()</code>, <code>StartScheduleTableAbs()</code>, <code>StopScheduleTable()</code>).\n</li></ul>\n</li><li><strong>Generator- &amp; Laufzeit-Validierung:</strong>\n<ul class=\"fig-list\"><li>Fehlt die Referenz im ECUC-File, verweigert der OS-Generator entweder die Codeerzeugung oder das OS quittiert den API-Zugriff zur Laufzeit mit dem Rückgabewert <code>E_OS_ACCESS</code>.\n</li></ul>\n</li></ul>"}, {"id": "FIG-e3d229e3361cddb2", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Objektdiagramm (M1-Instanziierungsebene des AUTOSAR ECU Configuration Metamodells).\n</li><li><strong>Technischer Zweck:</strong> Spezifikationsbeispiel zur Veranschaulichung der Modellierung von Referenzbeziehungen (<code>ReferenceParamDef</code>) zwischen Konfigurationscontainern (<code>ParamConfContainerDef</code>) innerhalb der BSW-Parametrisierung (ECUC Parameter Definition). \n</li><li><strong>Funktionale Einordnung:</strong> Dient als formale Schablone für Konfigurationsgeneratoren und XML-/ARXML-Schemata, demonstriert anhand der Zuordnung von OS-Schedule-Tables zu OS-Applications im AUTOSAR OS.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>OsApplication : ParamConfContainerDef</code></strong>\n<ul class=\"fig-list\"><li>Metamodell-Instanz zur Container-Definition einer OS-Applikation.\n</li><li>Attributierung: <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code> (in einer ECU-Konfiguration können null bis beliebig viele Instanzen dieses Containers existieren).\n</li></ul>\n</li><li><strong><code>OsAppScheduleTableRef : ReferenceParamDef</code></strong>\n<ul class=\"fig-list\"><li>Metamodell-Instanz zur Definition eines Referenzparameters.\n</li><li>Attributierung: <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code> (eine OS-Application kann null bis beliebig viele Schedule Tables referenzieren).\n</li></ul>\n</li><li><strong><code>OsScheduleTable : ParamConfContainerDef</code></strong>\n<ul class=\"fig-list\"><li>Metamodell-Instanz zur Definition des Ziel-Containers für Scheduling-Tabellen.\n</li><li>Attributierung: <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>.\n</li></ul>\n</li><li><strong>Beziehungen:</strong>\n<ul class=\"fig-list\"><li><strong>Komposition (<code>+reference</code>):</strong> Strenge Teil-Ganzes-Beziehung (ausgefüllte Raute bei <code>OsApplication</code>). Der Referenzparameter <code>OsAppScheduleTableRef</code> ist strukturell und existenziell im definierenden Container <code>OsApplication</code> gekapselt.\n</li><li><strong>Gerichtete Assoziation (<code>+destination</code>):</strong> Unidirektionale Zielreferenz (offene Pfeilspitze) von <code>OsAppScheduleTableRef</code> auf den Ziel-Container <code>OsScheduleTable</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Nicht zutreffend:</strong> Statisches Daten-/Metamodell-Diagramm ohne Laufzeitsequenz.\n</li><li><strong>Prozessuale Zuordnung (Design-/Generierungszeit):</strong> Die Auswertung der Referenz erfolgt rein statisch während des Konfigurations- und Generierungsschritts (Tooling). Das ECUC-Validierungswerkzeug prüft die Gültigkeit des Pfadverweises (<code>VALUE-REF</code>) und generiert daraus statische C-Deskriptoren, Bitmasken oder Konstantenarrays für das AUTOSAR OS.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Serialisierung:</strong> \n<ul class=\"fig-list\"><li>Im Konfigurationsmodell (<code>EcucParameterValues</code>) entspricht dies einem <code>EcucReferenceValue</code>, der innerhalb des übergeordneten <code>EcucContainerValue</code> (<code>OsApplication</code>) liegt und über dessen Zielpfad auf einen separaten <code>EcucContainerValue</code> (<code>OsScheduleTable</code>) zeigt.\n</li></ul>\n</li><li><strong>OS-Sicherheits- &amp; Rechtemodell:</strong>\n<ul class=\"fig-list\"><li>Konfiguriert im AUTOSAR OS die Zugriffsberechtigungen (<code>ACCESSING-APPLICATION</code>) bzw. Ownership-Relationen. Tasks oder ISRs, die der jeweiligen <code>OsApplication</code> zugeordnet sind, leiten hierüber ihr Recht ab, Steuerungs-APIs auf der Ziel-Schedule-Table aufzurufen (z. B. <code>StartScheduleTableRel()</code>, <code>StartScheduleTableAbs()</code>, <code>StopScheduleTable()</code>).\n</li></ul>\n</li><li><strong>Generator- &amp; Laufzeit-Validierung:</strong>\n<ul class=\"fig-list\"><li>Fehlt die Referenz im ECUC-File, verweigert der OS-Generator entweder die Codeerzeugung oder das OS quittiert den API-Zugriff zur Laufzeit mit dem Rückgabewert <code>E_OS_ACCESS</code>.\n</li></ul>\n</li></ul>"}, {"id": "FIG-cf3bed7a24733f27", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Objektdiagramm (M1-Instanziierungsebene des AUTOSAR ECU Configuration Metamodells).\n</li><li><strong>Technischer Zweck:</strong> Spezifikationsbeispiel zur Veranschaulichung der Modellierung von Referenzbeziehungen (<code>ReferenceParamDef</code>) zwischen Konfigurationscontainern (<code>ParamConfContainerDef</code>) innerhalb der BSW-Parametrisierung (ECUC Parameter Definition). \n</li><li><strong>Funktionale Einordnung:</strong> Dient als formale Schablone für Konfigurationsgeneratoren und XML-/ARXML-Schemata, demonstriert anhand der Zuordnung von OS-Schedule-Tables zu OS-Applications im AUTOSAR OS.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>OsApplication : ParamConfContainerDef</code></strong>\n<ul class=\"fig-list\"><li>Metamodell-Instanz zur Container-Definition einer OS-Applikation.\n</li><li>Attributierung: <code>upperMultiplicity = *</code>, <code>lowerMultiplicity = 0</code> (in einer ECU-Konfiguration können null bis beliebig viele Instanzen dieses Containers existieren).\n</li></ul>\n</li><li><strong><code>OsAppScheduleTableRef : ReferenceParamDef</code></strong>\n<ul class=\"fig-list\"><li>Metamodell-Instanz zur Definition eines Referenzparameters.\n</li><li>Attributierung: <code>upperMultiplicity = *</code>, <code>lowerMultiplicity = 0</code> (eine OS-Application kann null bis beliebig viele Schedule Tables referenzieren).\n</li></ul>\n</li><li><strong><code>OsScheduleTable : ParamConfContainerDef</code></strong>\n<ul class=\"fig-list\"><li>Metamodell-Instanz zur Definition des Ziel-Containers für Scheduling-Tabellen.\n</li><li>Attributierung: <code>upperMultiplicity = *</code>, <code>lowerMultiplicity = 0</code>.\n</li></ul>\n</li><li><strong>Beziehungen:</strong>\n<ul class=\"fig-list\"><li><strong>Komposition (<code>+reference</code>):</strong> Strenge Teil-Ganzes-Beziehung (ausgefüllte Raute bei <code>OsApplication</code>). Der Referenzparameter <code>OsAppScheduleTableRef</code> ist strukturell und existenziell im definierenden Container <code>OsApplication</code> gekapselt.\n</li><li><strong>Gerichtete Assoziation (<code>+destination</code>):</strong> Unidirektionale Zielreferenz (offene Pfeilspitze) von <code>OsAppScheduleTableRef</code> auf den Ziel-Container <code>OsScheduleTable</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Nicht zutreffend:</strong> Statisches Daten-/Metamodell-Diagramm ohne Laufzeitsequenz.\n</li><li><strong>Prozessuale Zuordnung (Design-/Generierungszeit):</strong> Die Auswertung der Referenz erfolgt rein statisch während des Konfigurations- und Generierungsschritts (Tooling). Das ECUC-Validierungswerkzeug prüft die Gültigkeit des Pfadverweises (<code>VALUE-REF</code>) und generiert daraus statische C-Deskriptoren, Bitmasken oder Konstantenarrays für das AUTOSAR OS.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ARXML-Serialisierung:</strong> \n<ul class=\"fig-list\"><li>Im Konfigurationsmodell (<code>EcucParameterValues</code>) entspricht dies einem <code>EcucReferenceValue</code>, der innerhalb des übergeordneten <code>EcucContainerValue</code> (<code>OsApplication</code>) liegt und über dessen Zielpfad auf einen separaten <code>EcucContainerValue</code> (<code>OsScheduleTable</code>) zeigt.\n</li></ul>\n</li><li><strong>OS-Sicherheits- &amp; Rechtemodell:</strong>\n<ul class=\"fig-list\"><li>Konfiguriert im AUTOSAR OS die Zugriffsberechtigungen (<code>ACCESSING-APPLICATION</code>) bzw. Ownership-Relationen. Tasks oder ISRs, die der jeweiligen <code>OsApplication</code> zugeordnet sind, leiten hierüber ihr Recht ab, Steuerungs-APIs auf der Ziel-Schedule-Table aufzurufen (z. B. <code>StartScheduleTableRel()</code>, <code>StartScheduleTableAbs()</code>, <code>StopScheduleTable()</code>).\n</li></ul>\n</li><li><strong>Generator- &amp; Laufzeit-Validierung:</strong>\n<ul class=\"fig-list\"><li>Fehlt die Referenz im ECUC-File, verweigert der OS-Generator entweder die Codeerzeugung oder das OS quittiert den API-Zugriff zur Laufzeit mit dem Rückgabewert <code>E_OS_ACCESS</code>.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-58885ed9769de68b", "to": "FIG-e3d229e3361cddb2", "fr": "R2.1.20", "tr": "R3.0.7", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong><code>OsAppScheduleTableRef</code>:</strong> Typ der Metamodell-Klasse von <code>ReferenceDef</code> auf <code>ReferenceParamDef</code> geändert.\n</li></ul>"}, {"from": "FIG-e3d229e3361cddb2", "to": "FIG-cf3bed7a24733f27", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>Attribute aller Objekte (<code>OsApplication</code>, <code>OsAppScheduleTableRef</code>, <code>OsScheduleTable</code>):</strong> Vertikale Reihenfolge der Multiplizitätsangaben vertauscht (<code>upperMultiplicity = *</code> steht nun vor <code>lowerMultiplicity = 0</code>).\n</li></ul>"}]};
